const J=JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES;
function readj($p){return json_decode(file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}
function savej($p,$v){file_put_contents(__DIR__.'/'.$p,json_encode($v,J));}
function ensure($v,$m){if(!$v)throw new RuntimeException($m);}
function ident($s){ensure((bool)preg_match('/^[a-zA-Z0-9_]+$/D',$s),'Invalid identifier');return '`'.$s.'`';}
function norm($u){$p=parse_url($u);$path=$p['path']??'';if(preg_match('~^/api/product-images/(\d+)/([^/]+)$~D',$path,$m))return 'local:products/'.$m[1].'/'.$m[2];if(str_starts_with($path,'/storage/'))return 'local:'.substr($path,9);return strtolower(($p['scheme']??'').'://'.($p['host']??'')).$path;}
$env=Dotenv\Dotenv::parse(file_get_contents(__DIR__.'/../../themmoik27be/.env'));
ensure(($env['DB_CONNECTION']??'')==='mysql'&&in_array($env['DB_HOST']??'',['localhost','127.0.0.1'],true)&&empty($env['DB_URL']),'Unexpected local MySQL');
function conn($name){global $env;return new PDO('mysql:host='.$env['DB_HOST'].';port='.($env['DB_PORT']??3306).';dbname='.$name.';charset=utf8mb4',$env['DB_USERNAME'],$env['DB_PASSWORD']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
function uat($name){ensure((bool)preg_match('/^sofep_image_restore_[0-9]{8}_[a-f0-9]{12}$/D',$name),'Refuse non-UAT database');$p=conn($name);ensure($p->query('SELECT DATABASE()')->fetchColumn()===$name,'Wrong database');return $p;}
function dumpdb($p){$out=[];$tables=$p->query("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")->fetchAll(PDO::FETCH_NUM);foreach($tables as $t){$name=$t[0];$cols=array_column($p->query('SHOW COLUMNS FROM '.ident($name))->fetchAll(PDO::FETCH_ASSOC),'Field');$out[$name]=['schema'=>$p->query('SHOW CREATE TABLE '.ident($name))->fetch(PDO::FETCH_NUM)[1],'rows'=>$p->query('SELECT * FROM '.ident($name).(in_array('id',$cols)?' ORDER BY id':''))->fetchAll(PDO::FETCH_ASSOC)];}ksort($out);return $out;}
function fp($dump){foreach($dump as &$x)$x['schema']=str_replace(' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',' COLLATE utf8mb4_unicode_ci',$x['schema']);unset($x);return hash('sha256',json_encode($dump));}
function insertRows($p,$table,$rows){foreach($rows as $r){$cols=array_keys($r);$s=$p->prepare('INSERT INTO '.ident($table).' ('.implode(',',array_map('ident',$cols)).') VALUES ('.implode(',',array_fill(0,count($cols),'?')).')');$s->execute(array_values($r));}}
function newClone($dump){global $env;$name='sofep_image_restore_'.gmdate('Ymd').'_'.bin2hex(random_bytes(6));$admin=conn('information_schema');$admin->exec('CREATE DATABASE '.ident($name).' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');file_put_contents(__DIR__.'/created-databases.log',$name.PHP_EOL,FILE_APPEND);$p=uat($name);$p->exec('SET FOREIGN_KEY_CHECKS=0');try{foreach($dump as $t=>$x)$p->exec($x['schema']);foreach($dump as $t=>$x)insertRows($p,$t,$x['rows']);}finally{$p->exec('SET FOREIGN_KEY_CHECKS=1');}savej('clone-last-dump.json',dumpdb($p));return [$name,$p];}
function fks($p){$q=$p->prepare('SELECT TABLE_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=? AND REFERENCED_TABLE_NAME IS NOT NULL');$q->execute([$p->query('SELECT DATABASE()')->fetchColumn()]);return $q->fetchAll(PDO::FETCH_ASSOC);}
function fkCheck($p){$out=[];foreach(fks($p) as $k){$sql='SELECT COUNT(*) FROM '.ident($k['TABLE_NAME']).' a LEFT JOIN '.ident($k['REFERENCED_TABLE_NAME']).' b ON a.'.ident($k['COLUMN_NAME']).'=b.'.ident($k['REFERENCED_COLUMN_NAME']).' WHERE a.'.ident($k['COLUMN_NAME']).' IS NOT NULL AND b.'.ident($k['REFERENCED_COLUMN_NAME']).' IS NULL';$n=(int)$p->query($sql)->fetchColumn();$out[]=$k+['orphans'=>$n];ensure($n===0,'Orphan FK');}return $out;}
function checkCandidates($p,$rows){$main=array_map('norm',$p->query('SELECT hinh_anh FROM san_phams WHERE hinh_anh IS NOT NULL')->fetchAll(PDO::FETCH_COLUMN));$orders=array_map('norm',$p->query('SELECT hinh_anh FROM chi_tiet_don_hangs WHERE hinh_anh IS NOT NULL')->fetchAll(PDO::FETCH_COLUMN));$fk=array_filter(fks($p),fn($f)=>$f['REFERENCED_TABLE_NAME']==='anh_san_phams');foreach($rows as $r){ensure(!in_array(norm($r['duong_dan_anh']),$main,true),'Candidate became main image');ensure(!in_array(norm($r['duong_dan_anh']),$orders,true),'Candidate used in order');foreach($fk as $k){$q=$p->prepare('SELECT COUNT(*) FROM '.ident($k['TABLE_NAME']).' WHERE '.ident($k['COLUMN_NAME']).'=?');$q->execute([$r['id']]);ensure((int)$q->fetchColumn()===0,'Candidate referenced by FK');}}ensure((int)$p->query('SELECT @@FOREIGN_KEY_CHECKS')->fetchColumn()===1,'FK checks disabled');}
