 $urlRefs=[];foreach($columns as $col){if(!in_array($col['DATA_TYPE'],['varchar','char','text','mediumtext','longtext'])||!preg_match('/(^hinh_anh$|^duong_dan_anh$|^anh_|image|photo|avatar)/i',$col['COLUMN_NAME']))continue;$t=$col['TABLE_NAME'];$c=$col['COLUMN_NAME'];foreach($p->query('SELECT '.ident($c).' AS url,COUNT(*) AS n FROM '.ident($t).' WHERE '.ident($c).' IS NOT NULL GROUP BY '.ident($c))->fetchAll(PDO::FETCH_ASSOC) as $r){$urlRefs[norm($r['url'])][]=['table'=>$t,'column'=>$c,'count'=>(int)$r['n']];}}
